    <div class="card-content">
      <ul>
        <!-- <li v-for="(value, key) in data" :key="key">
          <strong>{{ getFriendlyKey(key) }}:</strong> {{ value }}
        </li> -->
        <!-- <li>
          <strong>模板配置类型名称:</strong> {{ data.model_template_config_type_name }}
        </li> -->
        <li style="color: #1A5AFF;font-weight: bold;">
          {{ data.model_template_config_type_name }}
        </li>
        <li>
          <strong>模板名称:</strong> {{ data.template_small_name }}
        </li>
        <li v-for="(item,index) in data.list_data" :key="'card'+index">
