  <script>
export default {
  name: 'DataCard',
  props: {
    data: {
      type: Object,
      required: true
    }
  },
  data() {
    return {
      hover: false,
      keyMapping: {
        created_at: '创建时间',
        id: 'ID',
        model_template_config_type_id: '模型配置类型ID',
        model_template_config_type_name: '模型配置类型名称',
        template_small_end: '结束时间',
        template_small_gauss: '高斯参数',
