        template_small_number: '告警数量',
        template_small_start: '开始时间',
        template_small_threshold: '二值化阈值',
        template_small_upload: '上传时间',
        updated_at: '更新时间'
      },
      updateMsg: {},
      updateOpen: false,
    };
  },
  methods: {
    getFriendlyKey(key) {
      return this.keyMapping[key] || key;
    },
    handleUpdate() {
      this.$emit('cardClickUpdate', this.data)
    },
    handleDelete(){
      this.$emit('cardClickDelete', this.data)
    }
