<!-- 大类↓小类 -->
<template>
  <div id="modelSmall">
    <div class="search">
      <div class="jia_tab">
        <el-tag v-for="item in modelTypeOptions" :key="'标签'+item.id" @click="handleChangeModelType(item.id)">{{item.model_type_name}}</el-tag>
        <el-tag @click="handleChangeModelType()">全部</el-tag>
      </div>
      <el-form class="demo-ruleForm0" label-position="left">
        <!-- <el-form-item label="大类类型" prop="model_template_type_id">
          <el-select v-model="queryParams.model_template_type_id" placeholder="请选择大类类型" clearable filterable @change="axioss()">
            <el-option v-for="item in modelTypeOptions" :key="item.id+item.model_type_name" :label="item.model_type_name" :value="item.id"> </el-option>
          </el-select>
        </el-form-item> -->

        <el-form-item>
          <el-button icon="el-icon-search" type="primary" size="small" @click="axioss">搜索</el-button>
          <el-button icon="el-icon-plus" type="success" size="small" @click="handleAddCard">新增</el-button>
        </el-form-item>
      </el-form>
    </div>
    <div class="cardCon">
      <div class="card" v-for="item in tableData" :key="'表格'+item.id">
        <DataCard :data="item" @cardClickUpdate="handleUpdate" @cardClickDelete="handleDeleteCard"></DataCard>
      </div>
    </div>
    <!-- <el-table :data="tableData" style="width: 100%">
      <el-table-column prop="model_template_config_type_name" label="类型名称" width="180"></el-table-column>
      <el-table-column prop="template_small_name" label="模板名称"></el-table-column>
      <el-table-column prop="template_small_number" label="告警数量"></el-table-column>id
      <el-table-column prop="template_small_start" label="开始上报时间"></el-table-column>
      <el-table-column prop="template_small_end" label="结束上班时间"></el-table-column>
      <el-table-column prop="template_small_gauss" label="高斯参数"></el-table-column>
      <el-table-column prop="template_small_iou" label="IoU 阈值"></el-table-column>
      <el-table-column prop="template_small_threshold" label="二值化阈值"></el-table-column>
      <el-table-column prop="template_small_upload" label="上报间隔时间"></el-table-column>
      <el-table-column label="操作">
        <template slot-scope="scope">
          <el-button type="text" icon="el-icon-edit" size="mini" @click="handleUpdateModel(scope.row)">修改</el-button>
        </template>
      </el-table-column>
    </el-table> -->
    <!-- 编辑表单对话框 -->
    <el-dialog :title="dialogTitle" :visible.sync="dialogVisible">
      <el-form ref="formData" :model="editingForm" :rules="rules" label-width="120px">
        <el-form-item label="类型名称">
          <el-input v-model="editingForm.model_template_config_type_name"></el-input>
        </el-form-item>
        <el-form-item label="模板名称">
          <el-input v-model="editingForm.template_small_name"></el-input>
        </el-form-item>

        <el-form-item label="告警数量" v-if="numberOpen" prop="template_small_number">
          <el-input v-model="editingForm.template_small_number"></el-input>
        </el-form-item>

        <el-form-item label="高斯参数" v-if="conveyorTypeOpen" prop="template_small_gauss">
          <el-input v-model="editingForm.template_small_gauss"></el-input>
        </el-form-item>
        <el-form-item label="二值化阈值" v-if="conveyorTypeOpen" prop="template_small_threshold">
          <el-input v-model="editingForm.template_small_threshold"></el-input>
        </el-form-item>

        <el-form-item label="IoU 阈值" v-if="vehiclePedestrianStatsOpen" prop="template_small_iou">
          <el-input v-model="editingForm.template_small_iou"></el-input>
        </el-form-item>

        <el-form-item label="开始上报时间" v-if="countOpen" prop="template_small_start">
          <el-time-picker v-model="editingForm.template_small_start" :picker-options="{selectableRange: '00:00:00 - 23:59:59'}" placeholder="任意时间点" :default-value="new Date().setHours(0, 0, 0, 0)">
          </el-time-picker>
        </el-form-item>
        <el-form-item label="结束上报时间" v-if="countOpen" prop="template_small_end">
          <el-time-picker v-model="editingForm.template_small_end" :picker-options="{selectableRange: '00:00:00 - 23:59:59'}" placeholder="任意时间点" :default-value="new Date().setHours(0, 0, 0, 0)">
          </el-time-picker>
        </el-form-item>
        <el-form-item label="上传时间间隔" v-if="countOpen" prop="template_small_upload">
          <el-time-picker v-model="editingForm.template_small_upload" :picker-options="{selectableRange: '00:00:00 - 23:59:59'}" placeholder="任意时间点" :default-value="new Date().setHours(0, 0, 0, 0)">
          </el-time-picker>
        </el-form-item>
      </el-form>
      <span slot="footer" class="dialog-footer">
        <el-button @click="dialogVisible = false">取 消</el-button>
        <el-button type="primary" @click="saveEdit">保 存</el-button>
      </span>
    </el-dialog>

    <el-dialog :title="updateTitle" :visible.sync="updateOpen" width="50%">
      <el-form ref="formData" :model="updateMsg" label-width="120px" label-position="top">
        <el-form-item label="类型名称">
          <!-- <el-input v-model="updateMsg.model_template_config_type_name" placeholder="请输入类型名称"></el-input> -->
          <el-select v-model="updateMsg.model_template_config_type_id" placeholder="请选择大类类型" clearable filterable>
            <el-option v-for="item in modelTypeOptions" :key="item.id+item.model_type_name" :label="item.model_type_name" :value="item.id"> </el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="模板名称">
          <el-input v-model="updateMsg.template_small_name" placeholder="请输入模板名称"></el-input>
        </el-form-item>
        <el-form-item label="自定义内容">
          <div v-for="(item,index) in updateMsg.list_data" :key="'jia'+index">
            <div v-for="(value,key) in item" :key="key+value">
              <strong>{{ key }}:</strong> {{ value[0] }}
              <el-button icon="el-icon-minus" circle size="small" style="float: right;margin-right: 38px;" @click="handleDeleteUpdateMsg(index)"></el-button>
            </div>
          </div>
          <div style="color: #ff6600;">注意：点击右侧绿色按钮提交数据后再保存。</div>
          <el-input placeholder="请输入KEY" style="width: 30%;" v-model="updateKey"></el-input>
          <el-input placeholder="请输入VALUE" style="width: 20%;" v-model="updateValue"></el-input>
          <el-input placeholder="请输入备注" style="width: 30%;" v-model="updateMsgs"></el-input>
          <el-button type="success" icon="el-icon-folder" circle @click="handleAddUpdateMsg"></el-button>
        </el-form-item>
      </el-form>
      <span slot="footer" class="dialog-footer">
        <el-button @click="updateOpen = false;axioss()">取 消</el-button>
        <el-button type="primary" @click="saveEdit2">保 存</el-button>
      </span>
    </el-dialog>
  </div>
</template>
  
<script>
import { modelApi } from "@/api/model/index"
import { MessageBox } from "element-ui"
import DataCard from './DataCard.vue'
export default {
  name: 'modelSmall',
  components: {
    DataCard,
  },
  data() {
    // 定义验证规则
    const validateNonNegativeInteger = (rule, value, callback) => {
      // 如果值为空（包括 '', null, undefined），直接返回
      if (value === '' || value === null || value === undefined) {
        return callback();
      }

      // 尝试将值转换为整数
      const intValue = parseInt(value, 10);

      // 检查转换是否成功并且是有效非负整数
      if (isNaN(intValue) || !Number.isInteger(intValue) || intValue < 0) {
        return callback(new Error('请输入非负整数'));
      }

      // 成功通过验证
      callback();
    };

    const validateGaussianParam = (rule, value, callback) => {
      // 如果值为空，直接返回
      if (!value && value !== 0) return callback();

      // 尝试将值转换为整数
      const intValue = parseInt(value, 10);

      // 检查转换是否成功并且是有效整数
      if (isNaN(intValue) || !Number.isInteger(intValue)) {
        return callback(new Error('请输入有效的整数'));
      }

      // 验证范围和奇偶性
      if (intValue < 1 || intValue > 25 || intValue % 2 === 0) {
        callback(new Error('请输入1-25之间的奇数'));
      } else {
        callback();
      }
    };

    const validateBinaryThreshold = (rule, value, callback) => {
      // 如果值为空或0（有效输入），直接返回
      if (value === '' || value === null || value === undefined || value === 0) return callback();

      // 尝试将值转换为整数
      const intValue = parseInt(value, 10);

      // 检查转换是否成功并且是有效整数
      if (isNaN(intValue) || !Number.isInteger(intValue)) {
        return callback(new Error('请输入有效的整数'));
      }

      // 验证范围
      if (intValue < 0 || intValue > 255) {
        callback(new Error('请输入0-255之间的整数'));
      } else {
        callback();
      }
    };

    const validateIoU = (rule, value, callback) => {
      // 如果值为空，设置默认值为65并返回
      if (value === '' || value === null || value === undefined) {
        // 设置默认值，这取决于你如何处理表单数据
        // 这里假设你会在组件中处理默认值的设置
        // this.editingForm.template_small_iou = 65;
        return callback(); // 或者你可以选择在这里调用 callback(new Error('使用默认值65'));
      }

      // 尝试将值转换为整数
      const intValue = parseInt(value, 10);

      // 检查转换是否成功并且是有效整数
      if (isNaN(intValue) || !Number.isInteger(intValue)) {
        return callback(new Error('请输入有效的整数'));
      }

      // 验证范围
      if (intValue < 1 || intValue > 99) {
        callback(new Error('请输入1-99之间的整数'));
      } else {
        callback();
      }
    };
    return {
      queryParams: {
        page: 1,
        per_page: 15,
        model_template_type_id: '',
      },
      tableData: [
        // {
        //   created_at: null,
        //   id: 5,
        //   model_template_config_type_id: 1,
        //   model_template_config_type_name: "物体检测",
        //   template_small_end: null,
        //   template_small_gauss: null,
        //   template_small_iou: null,
        //   template_small_name: "通用模板",
        //   template_small_number: null,
        //   template_small_start: null,
        //   template_small_threshold: null,
        //   template_small_upload: null,
        //   updated_at: null
        // }
      ],
      dialogVisible: false, // 控制对话框显示状态
      dialogTitle: '',//对话框标题
      editingForm: {}, // 编辑表单的数据模型
      //编辑表单内控开关
      // 数量不足
      numberOpen: false,
      // 皮带、刮板机状态检测
      conveyorTypeOpen: false,
      // 行车不行人
      vehiclePedestrianStatsOpen: false,
      // 数量统计
      countOpen: false,
      rules: {
        template_small_number: [{ validator: validateNonNegativeInteger, trigger: 'blur' }],
        template_small_gauss: [{ validator: validateGaussianParam, trigger: 'blur' }],
        template_small_threshold: [{ validator: validateBinaryThreshold, trigger: 'blur' }],
        template_small_iou: [{ validator: validateIoU, trigger: 'blur', message: '请输入1-99之间的整数，默认65' }]
      },
      config: {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      },
      updateMsg: {},
      updateOpen: false,
      updateTitle: '',
      updateKey: '',
      updateValue: '',
      updateMsgs: '',
      modelTypeOptions: [],//大类类型字典
    };
  },
  created() {
    this.getModelType()
    this.axioss()
  },
  mounted() {

  },
  // 添加一个方法来格式化日期显示
  methods: {
    getModelType() {
      // 大类
      this.$http.get(modelApi.getModelType, {
        params: {
          page: 1,
          per_page: 999
        }
      }).then(response => {
        this.modelTypeOptions = response.data.data.data
      }).catch(rek => {
        console.log(rek)
      })
      // 模型类型
      // this.$http.get(dictApi.getDictDataList, {
      //   params: {
      //     type_code: 4,
      //     page: 1,
      //     per_page: 999,
      //   }
      // }).then(res => {
      //   if (res.data.code == 200) {
      //     this.modelTypeDict = res.data.data_list.data
      //   }
      // }).catch(rek => {
      //   console.log(rek)
      // })
    },
    // 查询表格数据
    axioss() {
      this.$http.get(modelApi.getModelSmallList, {
        params: this.queryParams
      }).then(response => {
        this.tableData = response.data.data.data;
        this.total = response.data.data.pagination.total_items;
      }).catch(rek => {
        console.log(rek)
      })
    },
    // 表格修改按钮
    handleUpdateModel(row) {
      this.numberOpen = false
      this.conveyorTypeOpen = false
      this.vehiclePedestrianStatsOpen = false
      this.countOpen = false
      this.$http.get(modelApi.getModelSmallDetail, {
        params: {
          id: row.id
        }
      }).then(response => {
        if (response.data.code == 200) {
          this.editingForm = response.data.data
          //进行四个类型开关判断
          if (response.data.data.template_small_name == "数量不足") {
            this.numberOpen = true
          } else if (response.data.data.template_small_name == "皮带、刮板机状态检测") {
            this.conveyorTypeOpen = true
          } else if (response.data.data.template_small_name == "行车不行人") {
            this.vehiclePedestrianStatsOpen = true
            this.editingForm.template_small_iou = 65
          } else if (response.data.data.template_small_name == "数量统计") {
            this.countOpen = true
          }
          this.dialogVisible = true
          this.dialogTitle = '编辑'
        }
      }).catch(rek => {
        console.log(rek)
      })
    },
    // 点击保存
    saveEdit() {
      this.$refs.formData.validate((valid) => {
        if (valid) {
          let form = new FormData();
          // 遍历 msg 对象，并将键值对添加到 formData 中
          Object.keys(this.editingForm).forEach(key => {
            form.append(key, this.editingForm[key]);
          });
          this.$http.post(modelApi.updateModelSmallList, form, this.config)
            .then(response => {
              if (response.data.code == 200) {
                this.$message({
                  type: "success",
                  message: response.data.msg
                })
              } else {
                this.$message({
                  type: "warning",
                  message: response.data.msg
                })
              }
              this.dialogVisible = false
              this.axioss()
            }).catch(rek => {
              console.log(rek)
            })
        }
      })
    },
    // 卡片修改按钮，触发函数
    handleUpdate(data) {
      this.updateOpen = true
      this.updateTitle = '编辑' + data.template_small_name
      this.updateMsg = data
      this.updateKey = ''
      this.updateValue = ''
    },
    // 卡片删除按钮，触发函数
    handleDeleteCard(row) {
      MessageBox.confirm('确定删除该数据吗？', '提示', {
        type: 'warning'
      }).then(() => {
        let data = {
          id: row.id
        }
        let form = new FormData()
        // 遍历 msg 对象，并将键值对添加到 formData 中
        Object.keys(data).forEach(key => {
          form.append(key, data[key]);
        });
        let config = {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        };
        this.$http.post(modelApi.deleteModelSmall, form, config)
          .then(response => {
            if (response.data.code == 200) {
              this.$message({
                type: 'success',
                message: response.data.msg
              })
            } else {
              this.$message({
                type: 'warning',
                message: response.data.msg
              })
            }
            this.axioss()
          })
          .catch(rek => {
            console.log(rek)
          })
      }).catch(() => {
        Message.info('已取消删除');
      });
    },
    saveEdit2() {
      let form = new FormData();
      let updateMsg = { ...this.updateMsg }
      updateMsg.list_data = JSON.stringify(updateMsg.list_data)
      // 遍历 msg 对象，并将键值对添加到 formData 中
      Object.keys(updateMsg).forEach(key => {
        form.append(key, updateMsg[key]);
      });
      if (this.updateTitle == '新增') {
        this.$http.post(modelApi.addModelSmall, form, this.config)
          .then(response => {
            if (response.data.code == 200) {
              this.$message({
                type: "success",
                message: response.data.msg
              })
            } else {
              this.$message({
                type: "warning",
                message: response.data.msg
              })
            }
            this.updateOpen = false
            this.axioss()
          }).catch(rek => {
            console.log(rek)
          })
      } else {
        this.$http.post(modelApi.updateModelSmallList, form, this.config)
          .then(response => {
            if (response.data.code == 200) {
              this.$message({
                type: "success",
                message: response.data.msg
              })
            } else {
              this.$message({
                type: "warning",
                message: response.data.msg
              })
            }
            this.updateOpen = false
            this.axioss()
          }).catch(rek => {
            console.log(rek)
          })
      }
    },
    handleAddUpdateMsg() {
      this.updateMsg.list_data.push({
        [this.updateKey]: [this.updateValue,this.updateMsgs]
      })
      this.updateKey = ''
      this.updateValue = ''
      this.updateMsgs = ''
    },
    handleDeleteUpdateMsg(index) {
      this.updateMsg.list_data.splice(index, 1)
    },
    // 新增按钮
    handleAddCard() {
      this.updateOpen = true
      this.updateTitle = '新增'
      this.updateKey = ''
      this.updateValue = ''
      this.updateMsg = {
        list_data: []
      }
    },
    handleChangeModelType(id){
      this.queryParams.model_template_type_id=id
      this.axioss();
    }
  }
};
</script>
  
<style lang="scss" scoped>
#modelSmall {
  width: 100%;
  height: 100%;
  background-color: #ffffff;
  border-radius: 6px;
  position: relative;
  .search {
    width: 100%;
    height: 70px;
    padding-top: 16px;
    padding-bottom: 16px;
    padding-left: 50px;
    box-sizing: border-box;
    position: absolute;
    top: 0;
    left: 0;
    z-index: 10;
    .demo-ruleForm0 {
      height: 70px;
      display: flex;
      justify-content: flex-start;
      align-items: flex-start;
      flex-wrap: wrap;
      float: left;
    }
    .jia_tab {
      width: 430px;
      height: 50px;
      float: left;
      .el-tag {
        margin-top: 5px;
        margin-right: 10px;
        cursor: pointer;
      }
    }
  }

  .cardCon {
    width: 100%;
    height: calc(100% - 70px);
    position: absolute;
    top: 70px;
    left: 0;
    overflow-y: scroll;
    .card {
      width: 338px;
      height: 359px;
      margin-left: 50px;
      margin-bottom: 10px;
      float: left;
    }
  }
}
</style>